<script setup lang="ts">
import { ref } from 'vue';
import { signup, resendVerify, failureOf } from './server';
const email=ref(''), password=ref(''), confirm=ref(''), busy=ref(false), sent=ref(false), notice=ref('');
const fields=ref<{name:string;reason:string}[]>([]);
function fail(e:unknown){const f=failureOf(e);notice.value=f.kind==='offline'?'미술관에 연결되지 않아요. 잠시 뒤 다시 시도해 주세요':f.kind==='login'?'다시 로그인해 주세요':f.reason;fields.value=f.kind==='refused'?f.fields:[];}
async function submit(){if(busy.value)return; notice.value='';fields.value=[];if(password.value!==confirm.value){notice.value='비밀번호가 서로 달라요. 다시 확인해 주세요';return;}busy.value=true;try{await signup({email:email.value.trim(),password:password.value,passwordConfirm:confirm.value});sent.value=true;password.value='';confirm.value='';}catch(e){fail(e);}finally{busy.value=false;}}
async function resend(){if(busy.value)return;busy.value=true;notice.value='';try{await resendVerify(email.value.trim());notice.value='확인 메일을 요청했어요. 메일함을 확인해 주세요';}catch(e){fail(e);}finally{busy.value=false;}}
</script>
<template><main class="auth"><section class="card" aria-labelledby="signup-title"><h1 id="signup-title">우리 미술관 시작하기</h1><template v-if="!sent"><p>보호자의 이메일로 가입해 주세요.</p><form @submit.prevent="submit"><label>이메일<input v-model="email" type="email" autocomplete="email" required maxlength="254" :disabled="busy"></label><label>비밀번호<input v-model="password" type="password" autocomplete="new-password" required minlength="8" maxlength="200" :disabled="busy"></label><label>비밀번호 확인<input v-model="confirm" type="password" autocomplete="new-password" required minlength="8" maxlength="200" :disabled="busy"></label><button :disabled="busy">{{busy?'가입하는 중':'가입하기'}}</button></form></template><template v-else><p role="status">확인 메일을 요청했어요. 메일의 링크를 열어 가입을 마쳐 주세요.</p><button type="button" :disabled="busy" @click="resend">확인 메일 다시 보내기</button></template><p v-if="notice" class="note" role="alert">{{notice}}</p><ul v-if="fields.length"><li v-for="(f,i) in fields" :key="i">{{f.name}}: {{f.reason}}</li></ul><RouterLink to="/app/world">미술관으로 돌아가기</RouterLink></section></main></template>
<style scoped>
.auth{min-height:100dvh;display:grid;place-items:center;padding:24px 16px;box-sizing:border-box;background:#fff8ec;color:#443529}.card{width:min(440px,100%);box-sizing:border-box;padding:24px;display:grid;gap:16px;border:1px solid #c9b38f;border-radius:18px;background:#fffdf8}h1{margin:0;font-size:26px}p{margin:0;line-height:1.6}form,label{display:grid;gap:8px}form{gap:16px}input{width:100%;box-sizing:border-box;min-height:44px;padding:10px;border:1px solid #bda881;border-radius:10px;font:inherit}button,a{min-height:44px}button{font:inherit;border:1px solid #ad557e;border-radius:10px;padding:10px 16px;background:#93405f;color:white;cursor:pointer}button:disabled{opacity:.6;cursor:wait}a{color:#78324f;display:inline-flex;align-items:center}ul{margin:0;padding-left:20px}.note{color:#8c302b}
</style>